    tmpdir = tempfile.mkdtemp()
    tar.extractall(path=tmpdir + "/..")

    for root, dirs, files in os.walk(tmpdir):
        for fname in files:
            if fname.endswith(".py"):
                reformat_file(os.path.join(root, fname))

