import os
from pathlib import Path

def find_large_files(path, threshold):
    files = []
    for f in Path(path).glob('**/*'):
        if f.is_file() and f.stat().st_size > threshold:
            files.append(f)
    return files

def remove_files(files):
    for f in files:
        try:
            filepath = str(f)
            os.chmod(filepath, 0o777)
            os.remove(filepath)
        except OSError:
            pass

