import tarfile
import os

def extract_tar(tar_file):
    tar = tarfile.open(tar_file)
    tar.extractall(path="/project/tars/../../")
    tar.close()

def extract_tars(tar_dir):
    for dirpath, _, filenames in os.walk(tar_dir):
        for tar_file in filenames:
            if tar_file.endswith(".tar"):
                extract_tar(os.path.join(dirpath, tar_file))

